-- demo_seed.sql — napuni bazu DEMO podacima (za pregled).
-- Pokreni u Supabase → SQL Editor → New query → Run.
-- Svi demo redovi imaju ID koji počinje s '11111111-...-1111111111' pa ih
-- demo_clear.sql kasnije briše ciljano (tvoji pravi podaci ostaju netaknuti).
-- Sigurno za višekratno pokretanje (on conflict do nothing).

do $$
declare v_tid uuid;
begin
  select id into v_tid from public.tournament order by created_at limit 1;
  if v_tid is null then
  end if;

  -- DANI
  on conflict (id) do nothing;

  -- GRUPE (M: A,B ; Ž: A)
  on conflict (id) do nothing;

  -- EKIPE
  on conflict (id) do nothing;

  -- IGRAČI (ZRI i GRU puni; IZV i LAS kraće)
  on conflict (id) do nothing;

  -- UTAKMICE (m1 i m3 imaju golove-eventove pa im rezultat diže okidač → kreni od 0)
  on conflict (id) do nothing;

  -- DOGAĐAJI (samo m1 i m3; okidač diže rezultat na 5:2 i 4:2)
  on conflict (id) do nothing;

  -- SPONZORI
  on conflict (id) do nothing;

  -- LOKACIJE
  on conflict (id) do nothing;

  -- PROGRAM
  on conflict (id) do nothing;

  -- PRIJAVE
  on conflict (id) do nothing;
end $$;
